CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 160), description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Planning', project_type text NOT NULL DEFAULT 'Web product', starting_stack text NOT NULL DEFAULT '', design_direction text NOT NULL DEFAULT '', complexity text NOT NULL DEFAULT 'Focused', repository_status text NOT NULL DEFAULT 'No repository yet', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY projects_own ON public.projects FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, project_id uuid, workspace_type text NOT NULL CHECK (workspace_type IN ('general','coding')), title text NOT NULL DEFAULT 'New conversation', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY (project_id,user_id) REFERENCES public.projects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_own ON public.conversations FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND (project_id IS NULL OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL CHECK (role IN ('user','assistant','system')), content text NOT NULL, model text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (conversation_id,user_id) REFERENCES public.conversations(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_own ON public.messages FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.project_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, user_id uuid NOT NULL, file_name text NOT NULL, file_type text NOT NULL, file_size bigint NOT NULL CHECK (file_size BETWEEN 0 AND 10485760), storage_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (project_id,user_id) REFERENCES public.projects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.project_files TO authenticated; GRANT ALL ON public.project_files TO service_role;
ALTER TABLE public.project_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY files_own ON public.project_files FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE TABLE public.project_memory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, user_id uuid NOT NULL, category text NOT NULL DEFAULT 'Note', content text NOT NULL, pinned boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (project_id,user_id) REFERENCES public.projects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.project_memory TO authenticated; GRANT ALL ON public.project_memory TO service_role;
ALTER TABLE public.project_memory ENABLE ROW LEVEL SECURITY;
CREATE POLICY memory_own ON public.project_memory FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, user_id uuid NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Next' CHECK(status IN ('Next','In progress','Done')), priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('Low','Medium','High')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (project_id,user_id) REFERENCES public.projects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tasks_own ON public.tasks FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid()));
CREATE TABLE public.activity_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid, user_id uuid NOT NULL, event_type text NOT NULL, title text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (project_id,user_id) REFERENCES public.projects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.activity_events TO authenticated; GRANT ALL ON public.activity_events TO service_role;
ALTER TABLE public.activity_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_own ON public.activity_events FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND (project_id IS NULL OR EXISTS (SELECT 1 FROM public.projects p WHERE p.id=project_id AND p.user_id=auth.uid())));
CREATE INDEX projects_user_recent ON public.projects(user_id,updated_at DESC); CREATE INDEX conversations_user_recent ON public.conversations(user_id,updated_at DESC); CREATE INDEX messages_thread_order ON public.messages(conversation_id,created_at); CREATE INDEX files_project ON public.project_files(project_id); CREATE INDEX memory_project ON public.project_memory(project_id,pinned DESC); CREATE INDEX tasks_project ON public.tasks(project_id,status); CREATE INDEX activity_project_recent ON public.activity_events(project_id,created_at DESC);
CREATE FUNCTION public.exodus_touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER touch_profiles BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.exodus_touch_updated_at(); CREATE TRIGGER touch_projects BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.exodus_touch_updated_at(); CREATE TRIGGER touch_conversations BEFORE UPDATE ON public.conversations FOR EACH ROW EXECUTE FUNCTION public.exodus_touch_updated_at(); CREATE TRIGGER touch_memory BEFORE UPDATE ON public.project_memory FOR EACH ROW EXECUTE FUNCTION public.exodus_touch_updated_at(); CREATE TRIGGER touch_tasks BEFORE UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.exodus_touch_updated_at();
CREATE FUNCTION public.exodus_create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(user_id,display_name) VALUES (NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER exodus_signup_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.exodus_create_profile();
CREATE POLICY exodus_storage_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='exodus-files' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY exodus_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='exodus-files' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id::text=(storage.foldername(name))[2] AND p.user_id=auth.uid()));
CREATE POLICY exodus_storage_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='exodus-files' AND (storage.foldername(name))[1]=auth.uid()::text);